            let tracked new_context_ghost = FCClientRequestResponseGhost {
                batch_perms: Some(batch_perms),
                cell_id,
                local_updates,
                fc_clients,
            };
            (Some(resp), Tracked(new_context_ghost))
        } else {
            let tracked new_context_ghost = FCClientRequestResponseGhost {
                batch_perms,
                cell_id,
                local_updates,
                fc_clients,
            };
            (None, Tracked(new_context_ghost))
        }
    }

